sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float cell;
uniform float lineWidth;
uniform float majorEvery;
uniform float majorWidth;
uniform float majorBoost;
uniform float angle;
uniform float2 anchor;
uniform float dots;
uniform float dotSize;
layout(color) uniform half4 lineColor;
uniform float blend;
uniform float amount;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float2 rot2(float2 p, float a) {
    float s = sin(a);
    float c = cos(a);
    return float2(p.x * c - p.y * s, p.x * s + p.y * c);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 p = rot2(coord - anchor * size, -radians(angle));
    float2 g = p / cell;
    float2 f = abs(fract(g + 0.5) - 0.5) * cell;
    float lineM = 1.0 - smoothstep(lineWidth * 0.5, lineWidth * 0.5 + 1.0, min(f.x, f.y));
    float me = max(majorEvery, 1.0);
    float2 fm = abs(fract(g / me + 0.5) - 0.5) * cell * me;
    float majorM = 1.0 - smoothstep(majorWidth * 0.5, majorWidth * 0.5 + 1.0, min(fm.x, fm.y));
    float m = max(lineM, majorM * majorBoost);
    if (dots > 0.5) m = max(m, 1.0 - smoothstep(dotSize * 0.5, dotSize * 0.5 + 1.0, length(f)));
    float3 o = mix(s, blendm(s, float3(lineColor.rgb), blend), saturate(m) * amount);
    return fin(c, float4(max(o, float3(0.0)) * c.a, c.a), 1.0);
}
